pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate, uint256 ethAmount) public {
        vm.assume(ethAmount > 0 && ethAmount <= 1_000_000 ether);
        vm.assume(ownerCandidate != address(0) && ownerCandidate != address(c) && ownerCandidate != address(this));
        // Set the owner by assigning to the public Owner variable via vm.prank during setup
        // Deploy with msg.sender = address(this), then transfer ownership
        c = new C();
        // We need to set Owner to ownerCandidate; use the constructor's effect and then pass ownership via a call
        // But Owner is immutable after constructor. Instead, we deploy as ownerCandidate directly.
        vm.prank(ownerCandidate);
        c = new C();
        // Now c.Owner() == ownerCandidate
        vm.deal(address(c), ethAmount);
        // Record balances before withdraw
        uint256 ownerBalanceBefore = ownerCandidate.balance;
        uint256 contractBalanceBefore = address(c).balance;
        // Owner calls withdraw
        bool ok;
        vm.prank(ownerCandidate);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        // If withdraw succeeded, the Owner's balance must increase by contractBalanceBefore.
        // If it failed, the Owner's balance must remain unchanged and contract balance unchanged.
        if (ok) {
            assertTrue(ownerCandidate.balance == ownerBalanceBefore + contractBalanceBefore - address(c).balance);
            // Equivalently, assert that the owner received exactly the withdrawn amount:
            // ownerCandidate.balance - ownerBalanceBefore == contractBalanceBefore - address(c).balance
        } else {
            assertTrue(ownerBalanceBefore == ownerCandidate.balance && contractBalanceBefore == address(c).balance);
        }
    }
}

