contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 dummy) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(depositAmount > 0);

        // Owner is always the deployer of setUp (address(this)).
        // Fund the contract so withdraw has Ether to move.
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool successDep,) = address(c).call{value: depositAmount}("");
        vm.assume(successDep);

        // Perform withdraw as Owner.
