pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 depositAmount) public {
        vm.assume(owner != address(0));
        vm.assume(depositAmount > 0);
        // Deploy a new C and decorate it so the fuzzed owner is the actual Owner
        c = new C();
        // Transfer ownership by coercing storage? No cheatcodes allowed beyond those listed.
        // We can set Owner by deploying as the fuzzed owner:
        vm.prank(owner);
        c = new C();

        // Deposit Ether into the contract
        vm.deal(address(this), depositAmount);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "balance must be positive");

        // Owner calls withdraw
        vm.prank(owner);
        try c.withdraw() {
            // Withdraw succeeded, contract balance must now be zero
            assertTrue(address(c).balance == 0);
        } catch {
            // If withdraw reverted, the balance must remain unchanged
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

